// reference m sets within paths (all of them for an empty mask) names a
// resource that exists.
func resolveReservationReferences(ctx context.Context, refs *repox.References, m *bookingv1.Reservation, paths []string) error {
	return nil
}

// queueReservationReferences makes u resolve m's external references within
// paths before it commits, as guard does for the repositories.
func queueReservationReferences(u *repox.Unit, m *bookingv1.Reservation, paths []string) {
}

// queueReservationDelete makes u consult name's referrers before it commits
// and publish the NOTIFY event after, as guard does for Delete.
func queueReservationDelete(u *repox.Unit, name string, purged bool) {
	refs := u.Conn().References
	if refs == nil {
		return
	}
	var check *repox.DeleteCheck
	u.Before(func(ctx context.Context) (err error) {
		check, err = refs.CheckDelete(ctx, "booking.acme.example/Reservation", name)
		return err
	})
	u.After(func(ctx context.Context) { check.Done(ctx, purged) })
}

// queueReservationPurge makes u ask name's referrers before it commits; the
// purge it queues keeps the row when *keep is true.
func queueReservationPurge(u *repox.Unit, name string) (keep *bool) {
	keep = new(bool)
	if refs := u.Conn().References; refs != nil {
		u.Before(func(ctx context.Context) error {
			*keep = refs.KeepOnPurge(ctx, "booking.acme.example/Reservation", name)
			return nil
		})
	}
	return keep
}
